export function minimumHeightTrees(n        , edges            )           {
if(n===1)return [0];const adj              =Array.from({length:n},()=>new Set        ());for(const [a,b] of edges){adj[a].add(b);adj[b].add(a);}let leaves=adj.flatMap((s,i)=>s.size===1?[i]:[]),remaining=n;while(remaining>2){remaining-=leaves.length;const next         =[];for(const leaf of leaves)for(const neighbor of adj[leaf]){adj[neighbor].delete(leaf);if(adj[neighbor].size===1)next.push(neighbor);}leaves=next;}return leaves.sort((a,b)=>a-b);
}

